cat << 'EOF' > extract.js
const fs = require('fs');

function extract(filename) {
  const buf = fs.readFileSync(filename);

  // Check ELF magic
  if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('Not an ELF file');
  }

  const is64 = buf[4] === 2;
  const isLE = buf[5] === 1;

  // Parse ELF header
  // For ELF64:
  // e_phoff is at offset 32 (8 bytes)
  // e_phentsize is at offset 54 (2 bytes)
  // e_phnum is at offset 56 (2 bytes)

  const phoff = Number(buf.readBigUInt64LE(32));
  const phentsize = buf.readUInt16LE(54);
  const phnum = buf.readUInt16LE(56);

  const result = {};

  for (let i = 0; i < phnum; i++) {
    const phOffset = phoff + i * phentsize;
    const p_type = buf.readUInt32LE(phOffset);
    const p_flags = buf.readUInt32LE(phOffset + 4);
    const p_offset = Number(buf.readBigUInt64LE(phOffset + 8));
    const p_vaddr = Number(buf.readBigUInt64LE(phOffset + 16));
    const p_filesz = Number(buf.readBigUInt64LE(phOffset + 32));
    const p_memsz = Number(buf.readBigUInt64LE(phOffset + 40));

    // PT_LOAD is type 1
    if (p_type === 1) {
      for (let addr = p_vaddr; addr < p_vaddr + p_filesz; addr += 4) {
        const fileOffset = p_offset + (addr - p_vaddr);
        if (fileOffset + 4 <= buf.length) {
          const val = buf.readInt32LE(fileOffset);
          result[addr.toString()] = val;
        }
      }
      // For bytes in memsz beyond filesz (like bss), often zero
      for (let addr = p_vaddr + p_filesz; addr < p_vaddr + p_memsz; addr += 4) {
        result[addr.toString()] = 0;
      }
    }
  }

  console.log(JSON.stringify(result, null, 2));
}

extract(process.argv[2] || 'a.out');
EOF
